import React from 'react';

const Bidders: React.FC = () => {
  return (
    <div>
      <h2>👨‍⚖️ Bidders</h2>

      <div
        style={{
          marginTop: 20,
          background: '#fff',
          padding: 24,
          borderRadius: 12,
          border: '1px solid #E2E8F0',
        }}
      >
        Bidder management table goes here.
      </div>
    </div>
  );
};

export default Bidders;
